// Original self-study questions and worked explanations written for Physics Atlas.
// These do not reproduce or purport to be solutions to any institution's question paper.
export const exercises = [
 {id:'turning-points',topic:'mechanics',title:'Find the allowed motion',level:'Core',question:'A particle of mass m moves in one dimension in V(x) = ½kx², with k > 0 and total energy E > 0. Find the turning points, the classically allowed region, and the speed at x = 0.',hint:'Kinetic energy cannot be negative. At a turning point the instantaneous speed is zero.',steps:['Conservation of energy gives E = ½mv² + ½kx².','At a turning point v = 0, so x² = 2E/k. The two turning points are x = ±√(2E/k).','The condition E − V(x) ≥ 0 restricts motion to −√(2E/k) ≤ x ≤ √(2E/k).','At x = 0 all the energy is kinetic, so the speed is √(2E/m).'],answer:'Turning points: ±√(2E/k). Maximum speed: √(2E/m).',check:'As E increases, both the amplitude and maximum speed increase as √E.'},
 {id:'central-torque',topic:'mechanics',title:'Why does internal torque vanish?',level:'Core',question:'Two particles interact through equal and opposite central forces F₁₂ and F₂₁. There is no external force. Show that the total angular momentum about a fixed inertial origin is conserved. Why does “central” matter?',hint:'Differentiate r × p. Combine the two torque terms before setting anything to zero.',steps:['For each particle, d(rᵢ × pᵢ)/dt = vᵢ × pᵢ + rᵢ × Fᵢ. Since pᵢ = mᵢvᵢ, the first cross product vanishes.','The total internal torque is r₁ × F₁₂ + r₂ × F₂₁ = (r₁ − r₂) × F₁₂.','A central force is parallel to the separation r₁ − r₂. Its cross product with that separation is zero.','Therefore dLtotal/dt = 0. Equal and opposite forces alone do not guarantee zero particle torque if the forces are not along the separation.'],answer:'The total particle angular momentum is conserved because the pair’s net internal torque is zero.',check:'In field-mediated interactions, angular momentum can also reside in the field.'},
 {id:'pendulum-lagrangian',topic:'mechanics',title:'A pendulum from least action',level:'Stretch',question:'A point mass m hangs from a massless rigid rod of length ℓ in a uniform gravitational field. Let θ be measured from the downward vertical. Find the equation of motion and the small-angle period.',hint:'Use T = ½mℓ²θ̇² and measure potential energy relative to the lowest point.',steps:['The potential is V = mgℓ(1 − cos θ), so L = ½mℓ²θ̇² − mgℓ(1 − cos θ).','The Euler–Lagrange equation is d(∂L/∂θ̇)/dt − ∂L/∂θ = 0.','This gives mℓ²θ̈ + mgℓ sin θ = 0, or θ̈ + (g/ℓ) sin θ = 0.','For |θ| ≪ 1 radian, sin θ ≈ θ. The angular frequency is √(g/ℓ), so the period is 2π√(ℓ/g).'],answer:'θ̈ + (g/ℓ) sin θ = 0. Small-angle period: 2π√(ℓ/g).',check:'The mass cancels. Large-amplitude oscillations do not have exactly this period.'},
 {id:'charged-sphere',topic:'electromagnetism',title:'Inside a uniformly charged sphere',level:'Core',question:'A sphere of radius R has constant volume charge density ρ. In vacuum, find E(r) for r < R and r > R. The distribution is spherically symmetric.',hint:'The charge inside a Gaussian sphere depends on its radius when the surface lies within the material.',steps:['Spherical symmetry makes E radial with a constant magnitude on a concentric Gaussian sphere.','For r < R, the enclosed charge is ρ(4πr³/3). Gauss’s law gives E·4πr² = ρ(4πr³/3)/ε₀.','Hence E(r) = ρr/(3ε₀) in the radial direction inside.','For r > R, the enclosed charge remains ρ(4πR³/3), so E(r) = ρR³/(3ε₀r²) in the radial direction.'],answer:'Einside = [ρr/(3ε₀)] r̂; Eoutside = [ρR³/(3ε₀r²)] r̂.',check:'The field is continuous at r = R and vanishes at the center. A negative ρ reverses its direction.'},
 {id:'box-flux',topic:'electromagnetism',title:'Flux without spherical symmetry',level:'Core',question:'The field E = αx x̂ fills a rectangular box 0 ≤ x ≤ a, 0 ≤ y ≤ b, 0 ≤ z ≤ c, where α is constant. Find the outward electric flux and enclosed charge.',hint:'Only two faces can contribute. Remember the outward normal on the x = 0 face.',steps:['The y-normal and z-normal faces have E · n̂ = 0.','At x = a, E · n̂ = αa over area bc. Its contribution is αabc.','At x = 0 the field itself is zero, so that face contributes zero.','The total flux is αabc. Gauss’s law then gives Qenc = ε₀αabc. Equivalently, ∇ · E = α gives the uniform density ρ = ε₀α.'],answer:'Flux = αabc; enclosed charge = ε₀αabc.',check:'Gauss’s law works without symmetry. Symmetry is useful when you need to infer E from the law.'},
 {id:'potential-work',topic:'electromagnetism',title:'What does potential tell you?',level:'Core',question:'A charge q is moved slowly from A to B in an electrostatic field. The potentials are V(A) = 12 V and V(B) = 5 V. Find the change in potential energy and the work done by the electric field for q = +2 μC.',hint:'Distinguish work done by the field from the change in the potential energy.',steps:['The potential difference is ΔV = V(B) − V(A) = −7 V.','Potential-energy change is ΔU = qΔV = (2 × 10⁻⁶ C)(−7 V) = −14 μJ.','The work done by the electrostatic field is Wfield = −ΔU = +14 μJ.','For a slow motion with negligible kinetic-energy change, an external agent would do −14 μJ of work.'],answer:'ΔU = −14 μJ. Wfield = +14 μJ.',check:'Potential is energy per unit charge. For a negative charge, the energy-change sign reverses.'},
 {id:'box-normalization',topic:'quantum',title:'Normalize the infinite-well state',level:'Core',question:'For an infinite square well with 0 < x < a, let ψₙ(x) = A sin(nπx/a), where n is a positive integer. Normalize the state and find its energy. Take A to be real and positive.',hint:'Use the fact that the average of sin² over an integer number of half-wavelengths is ½.',steps:['Normalization requires A² ∫₀ᵃ sin²(nπx/a) dx = 1.','The integral is a/2, so A = √(2/a).','Inside the well, V = 0. Applying −(ℏ²/2m)d²/dx² multiplies the state by n²π²ℏ²/(2ma²).','The wavefunction vanishes at both boundaries and is zero outside the well.'],answer:'ψₙ = √(2/a) sin(nπx/a), with Eₙ = n²π²ℏ²/(2ma²).',check:'The n = 0 expression is identically zero and is not a normalized state.'},
 {id:'spin-measurement',topic:'quantum',title:'A spin measurement in another basis',level:'Core',question:'A spin-½ particle is prepared in |+z⟩. What are the possible outcomes and probabilities when Sₓ is measured? What is ⟨Sₓ⟩?',hint:'Write |+z⟩ in the Sₓ eigenbasis.',steps:['Choose phases such that |+x⟩ = (|+z⟩ + |−z⟩)/√2 and |−x⟩ = (|+z⟩ − |−z⟩)/√2.','Then |+z⟩ = (|+x⟩ + |−x⟩)/√2.','Each amplitude has squared magnitude 1/2, so the outcomes +ℏ/2 and −ℏ/2 have equal probabilities.','The expectation value is (1/2)(+ℏ/2) + (1/2)(−ℏ/2) = 0.'],answer:'Outcomes ±ℏ/2, each with probability 1/2; ⟨Sₓ⟩ = 0.',check:'An expectation value of zero does not mean a measurement produces zero.'},
 {id:'partial-waves',topic:'quantum',title:'From phase shift to cross section',level:'Stretch',question:'For elastic scattering by a short-range central potential, only the s-wave contributes. Its phase shift is δ₀ = π/4 and the incident wave number is k. Find the total cross section. Ignore spin and identical-particle effects.',hint:'For one partial wave, σℓ = (4π/k²)(2ℓ + 1) sin²δℓ.',steps:['The s-wave has ℓ = 0, so its angular-momentum multiplicity is 2ℓ + 1 = 1.','Insert δ₀ = π/4. Since sin²(π/4) = 1/2, σ = (4π/k²)(1/2).','Thus σ = 2π/k². With only an s-wave the differential cross section is isotropic.','Indeed dσ/dΩ = sin²δ₀/k² = 1/(2k²), whose integral over 4π gives the same result.'],answer:'σtotal = 2π/k² and dσ/dΩ = 1/(2k²).',check:'The total cross section has dimensions of area. It is not a particle count.'},
 {id:'eigenvectors',topic:'mathematics',title:'The modes hidden in a matrix',level:'Core',question:'Find the eigenvalues and normalized eigenvectors of the real symmetric matrix A = [[2, 1], [1, 2]].',hint:'Try a vector with equal components, and one with opposite components.',steps:['For v = (1,1), Av = (3,3) = 3v. Thus λ = 3.','For w = (1,−1), Aw = (1,−1) = w. Thus λ = 1.','Each vector has Euclidean norm √2. Divide by √2 to normalize.','Their inner product is (1 − 1)/2 = 0, so they form an orthonormal eigenbasis.'],answer:'λ = 3 with (1,1)/√2; λ = 1 with (1,−1)/√2.',check:'For a two-oscillator problem, these often represent symmetric and antisymmetric normal modes.'},
 {id:'gaussian-integral',topic:'mathematics',title:'Scale a Gaussian integral',level:'Core',question:'Given ∫ from −∞ to ∞ of exp(−u²) du = √π, evaluate I(α) = ∫ from −∞ to ∞ of exp(−αx²) dx for α > 0. Then find the same integral with an additional factor x².',hint:'Rescale x first. Then differentiate the result with respect to α.',steps:['Let u = √α x. Then dx = du/√α, so I(α) = √π α⁻¹ᐟ².','Differentiating under the integral gives I′(α) = −∫ x² exp(−αx²) dx.','Differentiating the closed expression gives I′(α) = −(√π/2)α⁻³ᐟ².','Equating the two expressions yields the desired second-moment integral.'],answer:'I(α) = √(π/α); ∫ x²exp(−αx²) dx = √π/(2α³ᐟ²), over the full real line.',check:'If α has dimensions of inverse length squared, the two integrals have dimensions of length and length cubed.'},
 {id:'string-modes',topic:'waves',title:'The harmonics of a fixed string',level:'Core',question:'A string of length L is fixed at both ends and supports waves of speed v. Find its allowed wavelengths and frequencies. What changes when the tension is multiplied by four while the mass per unit length stays fixed?',hint:'An integer number of half-wavelengths must fit between the fixed ends.',steps:['The boundary conditions require L = nλₙ/2, for n = 1,2,3,…','Thus λₙ = 2L/n and fₙ = v/λₙ = nv/(2L).','For a stretched ideal string, v = √(T/μ), where T is the tension and μ is mass per length.','Multiplying T by four doubles v and therefore doubles every mode frequency. The allowed wavelengths stay fixed by L.'],answer:'λₙ = 2L/n and fₙ = nv/(2L). Quadrupling tension doubles all fₙ.'},
 {id:'isothermal-gas',topic:'thermal',title:'Reversible isothermal expansion',level:'Core',question:'An ideal gas containing N particles expands reversibly at temperature T from volume V to 2V. Find the work done by the gas, the heat absorbed, and the entropy change.',hint:'Use p = NkBT/V and the ideal-gas fact that internal energy depends only on temperature.',steps:['The work done by the gas is ∫ from V to 2V of p dV = NkBT ln 2.','For an ideal gas at constant temperature, ΔU = 0. Using ΔU = Q − Wgas gives Q = Wgas.','For a reversible isothermal process, ΔS = Qrev/T = NkB ln 2.'],answer:'Wgas = Q = NkBT ln 2; ΔS = NkB ln 2.',check:'For free expansion into a vacuum the work and heat can both be zero, while the entropy change between these same equilibrium states remains positive.'},
 {id:'carnot',topic:'thermal',title:'The best possible heat engine',level:'Core',question:'A reversible engine operates between reservoirs at 600 K and 300 K. It absorbs 1000 J from the hot reservoir per cycle. Find its efficiency, work output, and heat rejected.',hint:'Use absolute temperatures in η = 1 − Tc/Th.',steps:['The maximum reversible efficiency is 1 − 300/600 = 1/2.','The work output is ηQh = 500 J.','Energy conservation over a cycle gives Qc = Qh − W = 500 J.','The reservoir entropy changes cancel: −1000/600 + 500/300 = 0 J/K.'],answer:'Efficiency = 50%; work = 500 J; heat rejected = 500 J.',check:'Using Celsius in the efficiency formula would give an incorrect result.'},
 {id:'photon-truck',topic:'relativity',title:'Light inside a moving vehicle',level:'Core',question:'A vehicle travels at speed v relative to the ground. A photon moves forward at speed c relative to the vehicle. Use relativistic velocity addition to find its ground-frame speed.',hint:'Substitute u′ = c into u = (u′ + v)/(1 + u′v/c²).',steps:['Relativistic velocity addition gives u = (c + v)/(1 + v/c).','The numerator equals c(1 + v/c).','For an ordinary inertial vehicle with |v| < c, the factor cancels and u = c.'],answer:'The ground observer also measures the photon’s speed as c.',check:'Galilean velocity addition u = c + v is not valid for this situation.'},
 {id:'muon-lifetime',topic:'relativity',title:'How far can the muon travel?',level:'Core',question:'An idealized muon has proper mean lifetime 2.2 μs and travels at 0.8c in a laboratory. Take c = 3.0 × 10⁸ m/s. Find its mean lifetime and mean travel distance in the laboratory, neglecting energy loss.',hint:'The proper lifetime is measured in the muon’s rest frame. Use γ = 1/√(1 − v²/c²).',steps:['At v = 0.8c, γ = 1/√(1 − 0.64) = 5/3.','The lab mean lifetime is γτ₀ = (5/3)(2.2 μs) ≈ 3.67 μs.','The mean distance is vγτ₀ = (0.8)(3.0 × 10⁸)(3.67 × 10⁻⁶) m ≈ 880 m.'],answer:'Mean lab lifetime ≈ 3.67 μs; mean distance ≈ 880 m.',check:'Individual decays are random; these are mean values, not a fixed distance every muon travels.'},
 {id:'two-level',topic:'statistical',title:'The two-level partition function',level:'Core',question:'A system has two nondegenerate energy states, 0 and ε > 0, in equilibrium at temperature T. Find Z, the excited-state probability, and the mean energy.',hint:'Each state contributes a Boltzmann weight exp(−βE), where β = 1/(kBT).',steps:['The two weights are 1 and exp(−βε), so Z = 1 + exp(−βε).','The probability of the excited state is exp(−βε)/Z = 1/(exp(βε) + 1).','The mean energy is 0 times the ground-state probability plus ε times the excited-state probability.'],answer:'Z = 1 + exp(−βε); Pexc = 1/(exp(βε) + 1); ⟨E⟩ = ε/(exp(βε) + 1).',check:'At T → 0 the excited-state probability vanishes. At T → ∞ it approaches 1/2.'},
 {id:'double-slit',topic:'optics',title:'Read the double-slit pattern',level:'Core',question:'Light of wavelength 500 nm passes through two narrow slits separated by 0.50 mm. A screen is 2.0 m away. Find the spacing of adjacent bright fringes near the center, using the small-angle approximation.',hint:'The path difference is approximately d y / D. Adjacent bright fringes differ by one wavelength.',steps:['Constructive interference requires d sin θ = mλ.','Near the center, sin θ ≈ tan θ ≈ y/D, so ym ≈ mλD/d.','The spacing is Δy = λD/d = (500 × 10⁻⁹)(2.0)/(0.50 × 10⁻³) m.'],answer:'The fringe spacing is 2.0 mm.',check:'Increasing the slit separation makes the fringes closer together.'},
 {id:'hydrogen-line',topic:'atomic',title:'A hydrogen emission line',level:'Core',question:'Using the approximation Eₙ = −13.6 eV/n² for hydrogen, find the photon energy and wavelength for the n = 3 to n = 2 transition. Use hc = 1240 eV·nm.',hint:'The photon carries the positive difference between the initial and final atomic energies.',steps:['The initial energy is −13.6/9 eV and the final energy is −13.6/4 eV.','The emitted photon energy is Ei − Ef = 13.6(1/4 − 1/9) eV ≈ 1.889 eV.','Use λ = hc/Eγ = 1240/1.889 nm ≈ 656.5 nm.'],answer:'Eγ ≈ 1.89 eV and λ ≈ 657 nm at the stated precision.',check:'The atom loses energy while the emitted photon has positive energy.'},
 {id:'slater',topic:'quantum-chemistry',title:'The antisymmetric two-electron state',level:'Core',question:'Two electrons occupy orthonormal spin-orbitals χa and χb. Write their normalized antisymmetric two-particle state. What happens if you try to use the same spin-orbital twice?',hint:'Swap the particle labels. A fermionic state must change sign.',steps:['Start from the two products χa(1)χb(2) and χb(1)χa(2).','Their antisymmetric combination is Ψ = [χa(1)χb(2) − χb(1)χa(2)]/√2.','Orthonormality makes the cross terms in the norm vanish, and each product has norm one. The factor 1/√2 normalizes the sum.','If χa = χb, the two products cancel exactly. There is no nonzero two-electron state with both in the same spin-orbital.'],answer:'Ψ = [χa(1)χb(2) − χb(1)χa(2)]/√2.',check:'Two electrons may share a spatial orbital if their spin-orbitals differ, for example through opposite spin states.'},
 {id:'reciprocal-lattice',topic:'matter',title:'A one-dimensional Brillouin zone',level:'Core',question:'A one-dimensional crystal has lattice spacing a. Find the reciprocal-lattice vectors and the first Brillouin zone. What is the free-electron energy at the zone edge?',hint:'A reciprocal vector G must satisfy exp(iGa) = 1.',steps:['The phase condition gives Ga = 2πn, so Gn = 2πn/a.','The Wigner–Seitz cell around reciprocal origin G = 0 extends halfway to the nearest reciprocal points.','Thus the first Brillouin zone is −π/a ≤ k ≤ π/a.','For a free electron, E = ℏ²k²/(2m), giving Eedge = ℏ²π²/(2ma²).'],answer:'Gn = 2πn/a; first zone: [−π/a, π/a]; Eedge = ℏ²π²/(2ma²).',check:'A periodic potential can open a band gap at the zone boundary; the free-electron estimate alone does not include that gap.'},
 {id:'radioactive-decay',topic:'nuclear',title:'Three half-lives later',level:'Core',question:'A radioactive sample initially contains N₀ undecayed nuclei. Its half-life is 4 hours. What fraction remains after 12 hours, and what is the decay constant in inverse hours?',hint:'Use either repeated halving or N/N₀ = exp(−λt), with λt½ = ln 2.',steps:['Twelve hours corresponds to 12/4 = 3 half-lives.','The remaining fraction is (1/2)³ = 1/8.','From exp(−λt½) = 1/2, λ = ln 2/(4 h) ≈ 0.1733 h⁻¹.'],answer:'12.5% remains; λ ≈ 0.1733 h⁻¹.',check:'The expected decay rate λN also falls by a factor of eight.'},
 {id:'two-photons',topic:'particle',title:'The invariant mass of two photons',level:'Core',question:'Two photons, each with energy E, travel in opposite directions. Find the invariant mass of their combined system. What if the photons travel in the same direction instead?',hint:'Apply M²c⁴ = Etot² − |ptot|²c² to the system, not to an individual photon.',steps:['For opposite directions the momenta cancel, so Etot = 2E and ptot = 0.','Thus M²c⁴ = 4E², giving M = 2E/c².','For the same direction, |ptot| = 2E/c. Then Etot² − |ptot|²c² = 4E² − 4E² = 0.','Each photon is massless in both cases. The system invariant mass depends on their relative directions.'],answer:'Opposite directions: M = 2E/c². Same direction: M = 0.',check:'A system of massless particles can have a nonzero invariant mass.'},
 {id:'fixed-target',topic:'particle',title:'Fixed-target energy is not all available',level:'Stretch',question:'A projectile of rest mass m and total lab energy E strikes an identical particle at rest. Find the total center-of-momentum energy. Here E includes the projectile’s rest energy.',hint:'Square the sum of the two four-momenta. The target has zero spatial momentum.',steps:['The total lab energy is E + mc² and the total momentum is the projectile momentum p.','The system invariant gives Ecm² = (E + mc²)² − p²c².','For the projectile, E² − p²c² = m²c⁴. Substituting gives Ecm² = 2m²c⁴ + 2Emc².','At E ≫ mc², the leading behavior is Ecm ≈ √(2Emc²), rather than E + mc².'],answer:'Ecm = √(2m²c⁴ + 2Emc²).',check:'When the projectile is also at rest, E = mc² and Ecm = 2mc², as required.'},
 {id:'ladder',topic:'second-quantization',title:'Create one more boson',level:'Core',question:'For one bosonic mode with [a, a†] = 1 and normalized occupation states |n⟩, evaluate a†|3⟩, a|3⟩, and ⟨3|a†a|3⟩.',hint:'Use the normalized ladder relations. The square-root factors are essential.',steps:['The creation relation is a†|n⟩ = √(n + 1)|n + 1⟩, so a†|3⟩ = 2|4⟩.','The annihilation relation is a|n⟩ = √n|n − 1⟩, so a|3⟩ = √3|2⟩.','The number operator is N = a†a, with N|n⟩ = n|n⟩. Therefore the expectation value is 3.'],answer:'a†|3⟩ = 2|4⟩; a|3⟩ = √3|2⟩; ⟨N⟩ = 3.',check:'The unnormalized result of applying a† is not itself a normalized state. Divide by its norm when preparing the new state.'},
 {id:'klein-gordon',topic:'qft',title:'The equation of a free scalar field',level:'Stretch',question:'In natural units ℏ = c = 1 and metric signature (+,−,−,−), a real scalar field has ℒ = ½∂μφ ∂^μφ − ½m²φ². Derive its Euler–Lagrange field equation.',hint:'Use ∂μ[∂ℒ/∂(∂μφ)] − ∂ℒ/∂φ = 0.',steps:['Differentiation with respect to the field gradient gives ∂ℒ/∂(∂μφ) = ∂^μφ.','Differentiation with respect to the field gives ∂ℒ/∂φ = −m²φ.','The field Euler–Lagrange equation therefore becomes ∂μ∂^μφ + m²φ = 0.','With the given signature, ∂μ∂^μ = ∂t² − ∇².'],answer:'(□ + m²)φ = 0, or (∂t² − ∇² + m²)φ = 0.',check:'A plane wave gives the dispersion relation E² = |p|² + m² in these natural units.'},
 {id:'qcd-running',topic:'gauge',title:'Which way does the strong coupling run?',level:'Stretch',question:'For SU(3) QCD with nf active quark flavors, take the one-loop result dαs/d ln μ = −[β₀/(2π)]αs², with β₀ = 11 − 2nf/3. For nf = 6, does αs increase or decrease as μ increases?',hint:'Evaluate the coefficient and examine the sign of the derivative.',steps:['With nf = 6, β₀ = 11 − 4 = 7.','For positive αs, the derivative is −7αs²/(2π), which is negative.','Thus the strong coupling decreases with increasing energy scale in this approximation.','Integrating between scales with fixed nf gives 1/αs(μ) = 1/αs(μ₀) + [7/(2π)]ln(μ/μ₀).'],answer:'αs decreases as μ increases: the perturbative signature of asymptotic freedom.',check:'The one-loop expression is not reliable in the strongly coupled low-energy regime, and flavor thresholds change nf.'},
 {id:'schwarzschild-radius',topic:'gravity',title:'Scale a black-hole horizon',level:'Core',question:'For a nonrotating, uncharged black hole, the Schwarzschild radius is rs = 2GM/c². If M doubles, how do the horizon radius and area change? What is the horizon radius for one solar mass, using G = 6.67 × 10⁻¹¹ SI, M☉ = 1.99 × 10³⁰ kg, and c = 3.00 × 10⁸ m/s?',hint:'The radius is proportional to M. The area of a sphere is proportional to radius squared.',steps:['Since rs ∝ M, doubling the mass doubles the radius.','The horizon area A = 4πrs² is proportional to M², so it increases by a factor of four.','For one solar mass, rs = 2(6.67 × 10⁻¹¹)(1.99 × 10³⁰)/(3.00 × 10⁸)² m ≈ 2.95 × 10³ m.'],answer:'Radius doubles; area quadruples; rs(M☉) ≈ 2.95 km.',check:'These statements use the Schwarzschild solution. Rotation and charge require different formulas.'},
 {id:'stellar-luminosity',topic:'astrophysics',title:'A hotter star with the same radius',level:'Core',question:'Treat two stars as spherical blackbodies with equal radius. One has surface temperature T, the other 2T. What is their luminosity ratio? How do their peak wavelengths compare?',hint:'Combine L = 4πR²σT⁴ with Wien’s law λpeakT = constant.',steps:['At fixed radius, luminosity scales as T⁴.','Doubling T multiplies L by 2⁴ = 16.','Wien’s law makes the peak wavelength inversely proportional to T, so the hotter star’s peak wavelength is halved.'],answer:'The hotter star is 16 times as luminous and has half the peak wavelength.',check:'This is a blackbody approximation. Real stellar spectra also contain absorption lines and atmospheric effects.'},
 {id:'cosmic-redshift',topic:'cosmology',title:'Read the scale factor from redshift',level:'Core',question:'Normalize the present scale factor to a₀ = 1. A spectral line emitted at wavelength 121.6 nm is observed at 486.4 nm. Find the cosmological redshift and scale factor at emission.',hint:'Use 1 + z = λobs/λemit = a₀/aemit.',steps:['The wavelength ratio is 486.4/121.6 = 4.','Therefore 1 + z = 4 and z = 3.','With a₀ = 1, the emission scale factor is aemit = 1/4.'],answer:'z = 3 and aemit = 0.25.',check:'A redshift is not a distance by itself; converting it to a cosmological distance requires a model.'},
 {id:'fluid-continuity',topic:'fluids',title:'Flow through a narrowing pipe',level:'Core',question:'A steady incompressible fluid flows through a pipe. The cross-sectional area decreases from A to A/3. If the average speed in the wider section is v, what is the average speed in the narrower section?',hint:'The same volume must pass through each cross section per unit time.',steps:['Steady incompressible flow conserves volume flow rate Q = Av.','Thus Av = (A/3)v₂.','Canceling A gives v₂ = 3v.'],answer:'The speed in the narrow section is 3v.',check:'The result uses cross-sectional average speeds. Pressure changes need additional dynamical information.'},
 {id:'debye',topic:'plasma',title:'How does Debye screening scale?',level:'Core',question:'For a classical electron plasma with a fixed neutralizing ion background, use λD = √(ε₀kBTe/(nee²)). What happens to λD if electron density is multiplied by four while temperature remains fixed? What if temperature is also multiplied by four?',hint:'Debye length scales as the square root of temperature divided by density.',steps:['At fixed temperature, multiplying ne by four multiplies the denominator inside the square root by four.','The Debye length is therefore halved.','If both Te and ne are multiplied by four, their ratio is unchanged, so λD returns to its original value.'],answer:'Density ×4 alone: λD/2. Density ×4 and temperature ×4: unchanged λD.',check:'This expression assumes the classical electron screening model and is not universal for every plasma regime.'},
 {id:'su2-dimension',topic:'symmetry',title:'Count a spin multiplet',level:'Core',question:'An irreducible angular-momentum representation has j = 3/2. What is its dimension, and what are the allowed Jz eigenvalues? Is this an integer-spin or half-integer-spin representation?',hint:'The magnetic quantum number runs from −j to +j in steps of one.',steps:['The dimension is 2j + 1 = 4.','The allowed m values are −3/2, −1/2, +1/2, +3/2.','The Jz eigenvalues are mℏ.','Because j is half-integer, this is a half-integer-spin representation of SU(2).'],answer:'Dimension 4; Jz = −3ℏ/2, −ℏ/2, +ℏ/2, +3ℏ/2.',check:'The representation describes transformation properties; it does not by itself specify a particle’s mass or interaction.'},
 {id:'euler-step',topic:'computational',title:'Take a numerical integration step',level:'Core',question:'Use one explicit Euler step for ẋ = −kx, with x(0) = 1, k = 2 s⁻¹, and step size h = 0.1 s. Compare the result with the exact x(h), and find the condition on h for the Euler sequence to decay in magnitude when k > 0.',hint:'Explicit Euler uses the slope at the start: xₙ₊₁ = xₙ + h f(xₙ).',steps:['The update is xₙ₊₁ = (1 − kh)xₙ.','The first step gives x₁ = (1 − 0.2)(1) = 0.8.','The exact solution is exp(−kt), so x(0.1) = exp(−0.2) ≈ 0.81873.','Repeated steps decay in magnitude if |1 − kh| < 1, which gives 0 < h < 2/k. Nonoscillatory, nonnegative decay further requires h ≤ 1/k; at h = 1/k the first step reaches zero.'],answer:'Euler: 0.80000; exact: 0.81873; magnitude stability requires 0 < h < 2/k.',check:'A stable method can still have a significant discretization error.'},
 {id:'uncertainty',topic:'experimental',title:'Propagate a measured speed',level:'Core',question:'A distance is measured as d = (10.0 ± 0.2) m and a time as t = (2.00 ± 0.04) s. Treat the uncertainties as independent standard uncertainties. Find v = d/t and its first-order uncertainty.',hint:'For a ratio of independent measurements, add the squared relative uncertainties.',steps:['The nominal speed is v = 10.0/2.00 = 5.00 m/s.','The relative uncertainty is √[(0.2/10.0)² + (0.04/2.00)²] = √(0.02² + 0.02²) ≈ 0.02828.','Multiplying by v gives σv ≈ 0.1414 m/s.','Round the uncertainty and the value consistently.'],answer:'v = (5.00 ± 0.14) m/s.',check:'Correlated measurements require a covariance term; adding relative uncertainties in quadrature would then be incomplete.'},
 {id:'bell-state',topic:'quantum-information',title:'What does one half of a Bell pair know?',level:'Core',question:'Two qubits are in |Φ+⟩ = (|00⟩ + |11⟩)/√2. Find the probabilities for computational-basis joint measurements and the reduced density matrix of the first qubit.',hint:'The full state is pure, but tracing out one entangled subsystem can produce a mixed state.',steps:['The amplitudes for 00 and 11 are each 1/√2, so each occurs with probability 1/2. The outcomes 01 and 10 have probability zero.','Write ρAB = |Φ+⟩⟨Φ+| and trace over the second qubit.','The off-diagonal terms vanish under that partial trace because ⟨0|1⟩ = 0.','Thus ρA = ½|0⟩⟨0| + ½|1⟩⟨1| = I/2.'],answer:'P(00) = P(11) = 1/2; P(01) = P(10) = 0; ρA = I/2.',check:'The joint outcomes are perfectly correlated, even though either qubit alone is maximally mixed.'},
 {id:'fermion-occupation',topic:'many-body',title:'Occupying a single fermion mode',level:'Core',question:'For a single fermionic mode, {c,c†} = 1 and {c,c} = 0. Show that the number operator n = c†c satisfies n² = n. What occupation eigenvalues are allowed?',hint:'Use cc† = 1 − c†c, and note that c² = 0.',steps:['Compute n² = c†cc†c = c†(1 − c†c)c.','This is c†c − c†c†cc.','The second term vanishes because c² = 0 (and likewise (c†)² = 0). Hence n² = n.','If n|ν⟩ = ν|ν⟩, then ν² = ν, giving ν = 0 or 1.'],answer:'n² = n, and the single-mode occupations are 0 and 1.',check:'This restriction applies to one complete fermionic mode, including spin labels, not to a spatial orbital without specifying spin.'},
 {id:'diffusion-width',topic:'non-equilibrium',title:'The widening diffusion cloud',level:'Core',question:'A normalized one-dimensional distribution follows ∂tP = D∂x²P on the infinite line, with constant D and initial position x = 0. Find ⟨x²⟩ at time t, assuming the boundary terms vanish.',hint:'Differentiate ⟨x²⟩ = ∫x²P dx with respect to time and integrate by parts twice.',steps:['d⟨x²⟩/dt = D∫x²∂x²P dx.','Integrating by parts twice, with sufficiently fast decay at infinity, gives D∫2P dx = 2D.','Since the initial second moment is zero, integration over time gives ⟨x²⟩ = 2Dt.','The mean remains zero, so this is also the variance and the root-mean-square distance is √(2Dt).'],answer:'⟨x²⟩ = 2Dt and xrms = √(2Dt).',check:'The typical diffusion distance grows as √t, unlike constant-velocity ballistic motion, which grows as t.'},
 {"id":"nano-surface-scaling","topic":"nanomaterials","title":"Why do surfaces matter more at small sizes?","level":"Core","question":"A fixed amount of material is divided into identical spherical particles of radius R. Find the surface-area-to-volume ratio of one particle. If the radius is halved while the total material volume stays fixed, how do the number of particles and total exposed area change? Assume particles do not overlap or aggregate.","hint":"Use A = 4πR² and V = 4πR³/3. Keep the total material volume fixed when comparing particle counts.","steps":["For one sphere, A/V = (4πR²)/(4πR³/3) = 3/R.","Halving R reduces the volume of each particle by a factor of eight. Eight times as many particles are needed for the same total material volume.","Each smaller particle has one quarter of the original surface area. Multiplying by eight times as many particles gives twice the total surface area.","The increased exposed area per unit material helps explain why surface effects become more prominent as particle size decreases."],"answer":"A/V = 3/R. Halving R gives eight times as many particles and twice the total exposed area.","check":"This geometrical result assumes separate spheres. Aggregation can reduce the surface accessible to the environment."},
 {"id":"nano-confinement","topic":"nanomaterials","title":"How does confinement change an energy gap?","level":"Core","question":"Model one confined electron with effective mass m* in an ideal one-dimensional infinite well of width L. Using Eₙ = n²π²ℏ²/(2m*L²), find E₂ − E₁. If L is halved and m* remains constant, how do this gap and the corresponding photon wavelength change?","hint":"Subtract the n = 1 energy from the n = 2 energy. A resonant photon has energy hc/λ.","steps":["The n = 1 and n = 2 energies have coefficients 1 and 4, so ΔE = E₂ − E₁ = 3π²ℏ²/(2m*L²).","The gap is proportional to 1/L². Replacing L by L/2 multiplies ΔE by four.","Since λ = hc/ΔE, the corresponding wavelength is reduced to one quarter of its original value.","This model isolates quantum-confinement scaling. A real nanocrystal also involves band structure, finite barriers, and electron–hole interactions."],"answer":"ΔE = 3π²ℏ²/(2m*L²). Halving L quadruples the gap and quarters the photon wavelength.","check":"The result is a model level spacing, not a complete formula for a real semiconductor’s optical band gap."}
];
